/* One named asset: a still has a single frame, an animation has several, in
   order. Paths are relative to the repository root. */
/* Where a frame's own origin sits inside its exported image. Drawing the
   image with its top-left at (target - offset) puts the art exactly where the
   game draws it; without this, trimmed and padded exports land beside their
   mark. */
typedef struct {
    float x, y;
} AssetOffset;

typedef struct {
    const char        *name;
    const char        *category;
    const char *const *frames;
    const AssetOffset *offsets;   /* NULL when unknown */
    int32_t            frame_count;
    /* Where this art sits relative to its parent's origin, when known: the
       shape's bounds with its placement matrix applied. has_bounds is 0 for
       assets whose position the engine supplies instead. */
    int32_t            has_bounds;
    float              xmin, ymin, xmax, ymax;
} AssetEntry;

/* An animation state of the character model, as its frame labels define it.
   Frames are 1-based indices into the model's own frame list. */
typedef struct {
    const char *name;
    int32_t     start;
    int32_t     end;
    int32_t     length;
} AssetAnimation;

/* One part of the character model on one frame: the instance name and the
   matrix the model's timeline gives it. Matrices are SWF form --
   x' = a*x + c*y + tx, y' = b*x + d*y + ty -- with translation in pixels. */
typedef struct {
    const char *part;
    float       a, b, c, d, tx, ty;
} DollPlacement;

typedef struct {
    const DollPlacement *parts;
    int32_t              count;
} DollFrame;

/* How a doll part maps to equipment: `core` indexes the 7 equipment slots and
   `art` is the name used in the export ("M_<art>_<look>"). */
typedef struct {
    const char *part;
    int32_t     core;
    const char *art;
} DollPart;

/* Where the battle screen stands each unit, in stage coordinates, straight
   out of the original's own display list. The right-hand team's containers
   carry a negative horizontal scale, which is how the game mirrors them. */
typedef struct {
    int32_t slot;
    float   x, y;
    float   scale_x, scale_y;
    int32_t flip;
} StageSlot;

/* Where the health and focus bar for a slot sits, straight off the root
   timeline (p1BAR..p6BAR), with the bar art's own size. */
typedef struct {
    int32_t slot;
    float   x, y;          /* where the bar is placed */
    float   scale;         /* horizontal; the original's is not uniform */
    float   scale_y;
    float   width, height; /* the bar art's size */
    float   origin_x, origin_y;  /* where its own origin sits inside it */
} StageBar;

/* One piece of the battle screen's furniture, as the root timeline places it
   on the KRINBATTLESCENE frame: the top stats panel, the black battlefield
   backing, the three panels along the bottom, the turn indicator. `name` is
   the instance name where the original gave it one and "@<depth>" where it
   did not, and `depth` is the stacking order the original draws them in. The
   art is asset "#<character>", whose exported canvas is width x height with
   the piece's own origin at (origin_x, origin_y) inside it. */
typedef struct {
    const char *screen;    /* the root frame that places it */
    const char *name;
    int32_t     depth;
    int32_t     character;
    /* Non-zero when the placement is a mask rather than a picture: it clips
       everything above it up to this depth. The battle screen has one, which
       is what keeps the backdrop inside the battlefield frame. */
    int32_t     clip_depth;
    float       x, y;
    float       scale_x, scale_y;
    float       width, height;
    float       origin_x, origin_y;
} StageChrome;

/* One piece of the health/focus bar widget, in the bar's own coordinates.
   The parts in depth order are the black panel, the two fills, and a
   translucent gloss over them; the fills are drawn to a fraction of their
   width, which is how the bar shows a value. */
typedef struct {
    const char *name;
    int32_t     character;
    int32_t     depth;
    int32_t     clip_depth;   /* non-zero when the part is a mask */
    float       x, y;
    float       scale_x, scale_y;
    float       width, height;
    float       origin_x, origin_y;
} BarPart;

/* One of the bar's text fields, also in the bar's own coordinates. `side` is
   "left" or "right": the right-hand team's bars mirror the widget, and the
   original does that by running the text on its own second layout. `align` is
   the SWF's: 0 left, 1 right, 2 centre. `device` marks a field set in one of
   Flash's device fonts ("_sans"), which the player renders with a system face
   rather than with anything embedded in the file. */
typedef struct {
    const char *side;
    const char *role;      /* name, lifeNow, lifeMax, focusNow, focusMax */
    float       x, y;
    float       width, height;
    float       size;
    float       leading;   /* the gap the player leaves above the line */
    int32_t     align;
    int32_t     device;
    unsigned char r, g, b;
} BarField;

/* One of the eight orbs in the ability ring, in the ring's own coordinates.
   The player does not choose a move from a bar: hovering a unit brings up this
   ring around it, one orb per slot of the loadout, and clicking an orb uses
   that ability on that unit. */
typedef struct {
    int32_t slot;
    float   x, y;
    float   scale_x, scale_y;
} RingSlot;

/* A piece of the orb. It is built rather than drawn whole, because the clip's
   labelled frames have the black "cannot use this" disc in front of
   everything: a ball, the icon over it, a glass highlight, and that disc only
   when the ability is unusable. The icon is asset "<icon name>" in the orb
   category; `art` here is the shared piece, asset "#<character>". */
typedef struct {
    const char *role;      /* ball, mask, glass, filter */
    int32_t     character;
    int32_t     depth;
    float       x, y;
    float       scale_x, scale_y;
    float       width, height;
    float       origin_x, origin_y;
} OrbPart;

/* One drawable piece of a clip, in that clip's own coordinates. A clip that
   carries text fields cannot be exported whole -- the decompiler bakes the
   fields' design-time copy into the picture -- so its graphics are taken
   apart and the text drawn over them. `frames` is non-zero for a piece the
   game points at a frame of by name, like the speech box's portrait: its art
   is then the asset of that name rather than "#<character>". */
typedef struct {
    const char *owner;
    const char *name;
    int32_t     character;
    int32_t     depth;
    int32_t     frames;
    float       x, y;
    float       scale_x, scale_y;
    float       width, height;
    float       origin_x, origin_y;
} ClipPart;

/* One text field of the battle screen's furniture, in stage coordinates,
   straight off the DefineEditText tag: its box, the size and colour it is set
   in, its alignment (0 left, 1 right, 2 centre), the leading the player puts
   above the first line, and whether it uses one of Flash's device fonts.
   `owner` is the instance it belongs to, so the fields of something the game
   moves around -- a target's reticle, the speech box -- are taken relative to
   where that instance is placed. */
typedef struct {
    const char *screen;    /* the root frame that places its owner */
    const char *owner;     /* which clip it belongs to */
    const char *name;      /* the instance name inside that clip */
    float       x, y;
    float       width, height;
    float       size;
    float       leading;
    int32_t     align;
    int32_t     device;
    unsigned char r, g, b;
} TextField;

/* The two backdrop layers, which are containers rather than pictures: the
   game points each at the zone's own art on load, the sky with
   gotoAndStop(Krin.SkyBG) and the ground with gotoAndStop(Krin.ZoneBG). */
typedef struct {
    const char *name;      /* "sky" or "zone" */
    float       x, y;
    float       scale_x, scale_y;
} StageLayer;

/* Where a talent tree node sits on the stage. */
